class CsvExporter {
public:
  std::string quote(const std::string& f) {
    if (f.find(',') != std::string::npos) return "\"" + f + "\"";
    return f;
  }
};
class TsvExporter {
public:
  std::string quote(const std::string& f) {
    if (f.find('\t') != std::string::npos) return "\"" + f + "\"";
    return f;
  }
};
